def make_table(rows, columns):
    html = '<table><thead><tr>'
    for col in columns:
        html += f'<th>{col}</th>'
    html += '</tr></thead><tbody>'
    for row in rows:
        html += '<tr>'
        for col in columns:
            val = row.get(col, '')
            html += f'<td>{val}</td>'
        html += '</tr>'
    html += '</tbody></table>'
    return html

