<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<style>
  :root {{
    --accent: #1a73e8;
    --accent2: #ea4335;
    --accent3: #34a853;
    --bg: #ffffff;
    --surface: #f8f9fa;
    --border: #dee2e6;
    --text: #202124;
    --text-secondary: #5f6368;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: var(--text);
    background: var(--bg);
    line-height: 1.6;
  }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 24px; }}

  /* Header */
  .report-header {{
    background: linear-gradient(135deg, #0d47a1 0%, #1565c0 50%, #1a73e8 100%);
    color: #fff;
    padding: 48px 0 40px;
    margin-bottom: 0;
  }}
  .report-header h1 {{ font-size: 28px; font-weight: 700; letter-spacing: -0.5px; margin-bottom: 8px; }}
  .report-header .subtitle {{ font-size: 15px; opacity: 0.85; font-weight: 400; }}
  .report-header .meta {{ margin-top: 12px; font-size: 13px; opacity: 0.7; }}

  /* KPI Banner */
  .kpi-banner {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    padding: 32px 0;
    margin-top: -20px;
  }}
  .kpi-card {{
    background: var(--bg);
    border-radius: 10px;
    padding: 20px 18px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08), 0 0 0 1px rgba(0,0,0,0.04);
    text-align: center;
  }}
  .kpi-card .kpi-value {{
    font-size: 26px;
    font-weight: 700;
    color: var(--accent);
    margin-bottom: 4px;
  }}
  .kpi-card .kpi-label {{
    font-size: 12px;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 600;
  }}
  .kpi-card.highlight .kpi-value {{ color: var(--accent2); }}

  /* Sections */
  .section {{
    padding: 40px 0 24px;
    border-top: 1px solid var(--border);
  }}
  .section:first-of-type {{ border-top: none; }}
  .section h2 {{
    font-size: 22px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 8px;
    padding-left: 12px;
    border-left: 4px solid var(--accent);
  }}
  .section .section-desc {{
    color: var(--text-secondary);
    font-size: 14px;
    margin-bottom: 24px;
    padding-left: 16px;
  }}

  /* Charts */
  .chart-container {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
    margin-bottom: 20px;
    text-align: center;
  }}
  .chart-container img {{
    max-width: 100%;
    height: auto;
  }}

  /* Tables */
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 14px;
  }}
  thead th {{
    background: var(--accent);
    color: #fff;
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 13px;
  }}
  tbody td {{
    padding: 9px 14px;
    border-bottom: 1px solid var(--border);
  }}
  tbody tr:nth-child(even) {{ background: var(--surface); }}
  tbody tr:hover {{ background: #e8f0fe; }}

  /* Findings */
  .finding {{
    background: var(--surface);
    border-left: 4px solid var(--accent);
    padding: 14px 18px;
    margin: 12px 0;
    border-radius: 0 6px 6px 0;
    font-size: 14px;
  }}
  .finding.alert {{ border-left-color: var(--accent2); }}
  .finding strong {{ color: var(--accent); }}
  .finding.alert strong {{ color: var(--accent2); }}

  /* Two column layout */
  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}

  /* Footer */
  .report-footer {{
    text-align: center;
    padding: 32px 0;
    color: var(--text-secondary);
    font-size: 13px;
    border-top: 1px solid var(--border);
    margin-top: 32px;
  }}

  @media (max-width: 800px) {{
    .kpi-banner {{ grid-template-columns: repeat(2, 1fr); }}
    .two-col {{ grid-template-columns: 1fr; }}
  }}
</style>
</head>
<body>

<!-- ═══════ HEADER ═══════ -->
<div class="report-header">
  <div class="container">
    <h1>Active Satellites in Earth Orbit</h1>
    <div class="subtitle">2026 Catalog Analysis &mdash; 14,875 Active Spacecraft in the Orbital Environment</div>
    <div class="meta">Data source: CelesTrak / NORAD TLE &bull; Epoch range: {epoch_min} to {epoch_max}</div>
  </div>
</div>

<!-- ═══════ KPI BANNER ═══════ -->
<div class="container">
  <div class="kpi-banner">
    <div class="kpi-card">
      <div class="kpi-value">{total_sats:,}</div>
      <div class="kpi-label">Total Active Satellites</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{leo_share:.1f}%</div>
      <div class="kpi-label">LEO Share</div>
    </div>
    <div class="kpi-card highlight">
      <div class="kpi-value">{starlink_count:,}</div>
      <div class="kpi-label">Starlink Constellation</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{median_inclination:.1f}&deg;</div>
      <div class="kpi-label">Median Inclination</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{post_2020_count:,}</div>
      <div class="kpi-label">Launched Since 2020 ({post_2020_share:.0f}%)</div>
    </div>
  </div>

  <!-- ═══════ SECTION 1: OVERVIEW ═══════ -->
  <div class="section">
    <h2>1. Catalog Overview &amp; Key Figures</h2>
    <div class="section-desc">
      The catalog contains {total_sats:,} active satellites with orbital element sets dated {epoch_min} through {epoch_max}.
      Below is a summary of the core orbital parameters across the full population.
    </div>

    <div class="two-col">
      <div class="finding">
        <strong>Mean Inclination:</strong> {mean_incl:.1f}&deg; &nbsp;|&nbsp; <strong>Median:</strong> {median_inclination:.1f}&deg;<br>
        The inclination distribution is bimodal: a large cluster near 53&deg; (Starlink shells) and another near 97&deg; (Sun-synchronous LEO).
      </div>
      <div class="finding">
        <strong>Mean Eccentricity:</strong> {mean_ecc:.6f} &nbsp;|&nbsp; <strong>Median:</strong> {median_ecc:.6f}<br>
        The vast majority of active satellites operate in near-circular orbits (e &lt; 0.01).
      </div>
    </div>
    <div class="finding">
      <strong>Mean Motion:</strong> {mean_mm:.2f} rev/day &nbsp;|&nbsp;
      The average is pulled toward LEO by the dominant mega-constellations. The median is substantially higher, reflecting the LEO-heavy population.
    </div>
  </div>

  <!-- ═══════ SECTION 2: ORBITAL REGIME ═══════ -->
  <div class="section">
    <h2>2. Orbital Regime Classification</h2>
    <div class="section-desc">
      Satellites are classified by <strong>MEAN_MOTION</strong> thresholds: LEO (&gt;14 rev/day), MEO (1.8&ndash;14 rev/day),
      GEO (0.9&ndash;1.8 rev/day), and HEO (eccentricity &gt; 0.1 with mean motion &lt; 10 rev/day).
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_regime}" alt="Orbital Regime Distribution">
    </div>

    {regime_html}

    <div class="finding">
      <strong>LEO dominance is overwhelming:</strong> {leo_share:.1f}% of all active satellites reside in Low Earth Orbit.
      This concentration is almost entirely driven by Starlink and OneWeb broadband constellations.
    </div>
    <div class="finding alert">
      <strong>GEO remains strategically critical but numerically small:</strong> Only {int(regime_counts.get('GEO', 0)):,} active GEO satellites,
      yet they carry the majority of global communications and weather-observation bandwidth.
    </div>
  </div>

  <!-- ═══════ SECTION 3: CONSTELLATION ANALYSIS ═══════ -->
  <div class="section">
    <h2>3. Major Constellation &amp; Operator Breakdown</h2>
    <div class="section-desc">
      Constellation membership is identified by parsing the OBJECT_NAME prefix. The Starlink mega-constellation
      alone accounts for a decisive share of the entire active fleet.
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_constellations}" alt="Top Constellations">
    </div>

    <div class="two-col">
      <div class="chart-container">
        <img src="data:image/png;base64,{chart_starlink_impact}" alt="Starlink vs Rest">
      </div>
      <div>
        {const_html}
      </div>
    </div>

    <div class="finding alert">
      <strong>Starlink comprises {starlink_count/total_sats*100:.1f}% of all active satellites.</strong>
      Its dominance reshapes every aggregate statistic &mdash; from the global inclination peak near 53&deg; to the LEO share exceeding {leo_share:.0f}%.
      Any analysis of the orbital environment must account for this single-operator skew.
    </div>
    <div class="finding">
      <strong>After Starlink, the constellation landscape is fragmented:</strong> OneWeb, Iridium, GPS, and others each represent
      1&ndash;3% of the active fleet. No other single operator approaches Starlink's scale.
    </div>
  </div>

  <!-- ═══════ SECTION 4: LAUNCH TRENDS ═══════ -->
  <div class="section">
    <h2>4. Launch Year Trends</h2>
    <div class="section-desc">
      Launch year is extracted from the first four characters of OBJECT_ID. The chart below shows both annual
      launch counts and the cumulative size of the currently active fleet.
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_launch}" alt="Launch Year Trends">
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_launch_constellations}" alt="Launch Activity by Constellation">
    </div>

    <div class="finding alert">
      <strong>Post-2020 acceleration is the defining feature of this catalog.</strong>
      {post_2020_count:,} satellites ({post_2020_share:.1f}% of the active fleet) were launched in 2020 or later.
      This rapid growth is almost entirely attributable to Starlink deployments, which began in earnest in 2019 and have
      dominated launch manifests ever since.
    </div>

    <div class="finding">
      <strong>Before 2019, annual launch counts rarely exceeded 150 active satellites per year.</strong>
      The shift from dozens to thousands per year represents a fundamental change in the orbital environment's growth rate.
    </div>

    {decade_html}
  </div>

  <!-- ═══════ SECTION 5: ORBITAL PARAMETERS ═══════ -->
  <div class="section">
    <h2>5. Orbital Parameter Deep Dive</h2>
    <div class="section-desc">
      Distributions of inclination, eccentricity, and mean motion reveal the dominant orbital shells and highlight
      outliers such as polar and highly elliptical orbits.
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_inclination}" alt="Inclination Distribution">
    </div>

    <div class="finding">
      <strong>Inclination is sharply bimodal.</strong> The largest peak near 53&deg; corresponds to Starlink's operational shells.
      A secondary peak near 97&ndash;98&deg; reflects the Sun-synchronous orbit (SSO) band used by Earth-observation missions.
      Smaller clusters appear near 0&deg; (equatorial/GEO) and 86&ndash;90&deg; (polar).
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_mean_motion}" alt="Mean Motion Distribution">
    </div>

    <div class="finding">
      <strong>Mean motion clusters tightly at three regimes:</strong> ~15.0 rev/day (LEO, ~550 km altitude),
      ~1.0 rev/day (GEO), and ~2.0 rev/day (MEO navigation constellations like GPS and GLONASS).
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_eccentricity}" alt="Eccentricity Distribution">
    </div>

    <div class="finding">
      <strong>Nearly all active satellites have eccentricity &lt; 0.01</strong> (near-circular orbits).
      The long tail includes Molniya-type HEO orbits (e ~ 0.5&ndash;0.7) and GTO transfer orbits.
    </div>

    <div class="chart-container">
      <img src="data:image/png;base64,{chart_incl_box}" alt="Inclination by Regime">
    </div>

    <div class="finding">
      <strong>LEO spans the widest inclination range</strong> (equatorial to polar), reflecting diverse mission types.
      MEO concentrates near 55&ndash;56&deg; (navigation constellations) and 64&ndash;65&deg; (GLONASS).
      GEO satellites cluster tightly near 0&deg; inclination, as expected for geostationary operations.
    </div>
  </div>

  <!-- ═══════ SECTION 6: CONCLUSIONS ═══════ -->
  <div class="section">
    <h2>6. Key Takeaways &amp; Outlook</h2>

    <div class="finding alert">
      <strong>1. LEO is now the dominant orbital environment by an order of magnitude.</strong>
      {leo_share:.1f}% of all active satellites occupy LEO, driven almost entirely by commercial broadband constellations.
      Spectrum coordination and collision-avoidance frameworks in LEO are now as critical as GEO slot allocation was in the past.
    </div>

    <div class="finding alert">
      <strong>2. A single operator can reshape global orbital statistics.</strong>
      Starlink's {starlink_count:,} satellites ({starlink_count/total_sats*100:.1f}% of the active fleet) dominate the
      inclination distribution, LEO share, and recent launch volume. Policy analyses that treat the satellite population
      as diverse must account for this extreme concentration.
    </div>

    <div class="finding">
      <strong>3. The active fleet is exceptionally young.</strong>
      {post_2020_share:.1f}% of satellites were launched since 2020, meaning the majority of the current orbital
      population did not exist six years ago. This has implications for debris modeling: the long-term sustainability
      of this growth rate is unproven.
    </div>

    <div class="finding">
      <strong>4. GEO remains strategically disproportionate.</strong>
      With only {int(regime_counts.get('GEO', 0)):,} active satellites, GEO carries communications, weather, and
      surveillance missions that affect billions of users. LEO congestion does not reduce the need for GEO governance.
    </div>

    <div class="finding">
      <strong>5. The growth rate shows no sign of plateauing.</strong>
      Starlink continues to expand, and other mega-constellations (e.g., Amazon's Kuiper) are in early deployment.
      If current trends continue, the active satellite count could double within the decade.
    </div>
  </div>

</div>

<div class="report-footer">
  <div class="container">
    Active Satellites in Earth Orbit &mdash; 2026 Catalog Analysis<br>
    Data: CelesTrak / NORAD TLE &bull; Report generated from catalog data &bull; All statistics derived exclusively from <code>data.csv</code>
  </div>
</div>

</body>
</html>
"""

with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
    f.write(html)

print(f"Report written to /app/output/final_report.html")
print(f"Total satellites: {total_sats:,}")
print(f"LEO share: {leo_share:.1f}%")
print(f"Starlink: {starlink_count:,}")
print(f"Median inclination: {median_inclination:.1f}°")
print(f"Post-2020: {post_2020_count:,} ({post_2020_share:.1f}%)")
print(f"Regime counts: {dict(regime_counts)}")

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
from io import BytesIO
import warnings
warnings.filterwarnings('ignore')

# ─── Load & Clean Data ───────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
total_sats = len(df)

# Convert string columns
df['ECCENTRICITY'] = df['ECCENTRICITY'].astype(str).str.strip()
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')

df['MEAN_MOTION'] = pd.to_numeric(df['MEAN_MOTION'], errors='coerce')
df['INCLINATION'] = pd.to_numeric(df['INCLINATION'], errors='coerce')

# Extract launch year from OBJECT_ID (first 4 chars)
df['LAUNCH_YEAR'] = df['OBJECT_ID'].astype(str).str[:4].astype(int)

# ─── Orbital Regime Classification ───────────────────────────────────
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if pd.isna(mm):
        return 'Unknown'
    if ecc is not None and not pd.isna(ecc) and ecc > 0.1 and mm < 10:
        return 'HEO'
    if mm > 14:
        return 'LEO'
    elif mm >= 1.8:
        return 'MEO'
    elif mm >= 0.9:
        return 'GEO'
    else:
        return 'Other'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# ─── Constellation Identification ────────────────────────────────────
def identify_constellation(name):
    name_upper = str(name).upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    elif name_upper.startswith('GPS'):
        return 'GPS'
    elif name_upper.startswith('COSMO-SKYMED') or name_upper.startswith('COSMO'):
        return 'COSMO-SkyMed'
    elif name_upper.startswith('GONETS'):
        return 'Gonets'
    elif name_upper.startswith('GLONASS') or name_upper.startswith('COSMOS') and 'GLONASS' in name_upper:
        return 'GLONASS'
    elif name_upper.startswith('SENTINEL'):
        return 'Sentinel'
    elif name_upper.startswith('PLANET') or name_upper.startswith('FLOCK') or 'DOVE' in name_upper:
        return 'Planet Labs'
    elif name_upper.startswith('YAOGAN'):
        return 'Yaogan'
    elif name_upper.startswith('BEIDOU') or name_upper.startswith('BDS'):
        return 'BeiDou'
    elif name_upper.startswith('GLOBALSTAR'):
        return 'Globalstar'
    elif name_upper.startswith('ORBCOMM'):
        return 'Orbcomm'
    elif name_upper.startswith('SKYSAT'):
        return 'SkySat'
    elif name_upper.startswith('LEO'):
        return 'LEO (various)'
    elif name_upper.startswith('ISS') or name_upper == 'ISS (ZARYA)':
        return 'ISS'
    elif name_upper.startswith('TDRS'):
        return 'TDRS'
    elif name_upper.startswith('NOAA') or name_upper.startswith('GOES'):
        return 'NOAA/GOES'
    elif name_upper.startswith('LANDSAT'):
        return 'Landsat'
    elif name_upper.startswith('SWARM') and ('A' in name_upper or 'B' in name_upper):
        return 'Swarm'
    else:
        return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

# ─── Compute KPIs ────────────────────────────────────────────────────
leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = leo_count / total_sats * 100
starlink_count = len(df[df['CONSTELLATION'] == 'Starlink'])
median_inclination = df['INCLINATION'].median()
post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])
post_2020_share = post_2020_count / total_sats * 100

# ─── Chart Style Setup ───────────────────────────────────────────────
plt.rcParams.update({
    'figure.facecolor': '#ffffff',
    'axes.facecolor': '#f8f9fa',
    'axes.edgecolor': '#dee2e6',
    'axes.grid': True,
    'grid.color': '#e9ecef',
    'grid.linewidth': 0.6,
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.titlesize': 14,
    'axes.titleweight': 'bold',
    'axes.labelsize': 12,
})

ACCENT = '#1a73e8'
ACCENT2 = '#ea4335'
ACCENT3 = '#34a853'
ACCENT4 = '#fbbc04'
PALETTE = ['#1a73e8', '#ea4335', '#34a853', '#fbbc04', '#9c27b0', '#ff6d00', '#00bcd4', '#795548', '#607d8b', '#e91e63']

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=130)
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode()

# ═══════════════════════════════════════════════════════════════════════
# CHART 1 — Launch Year Trend (THE MOST IMPORTANT CHART)
# ═══════════════════════════════════════════════════════════════════════
launch_counts = df.groupby('LAUNCH_YEAR').size().reset_index(name='COUNT')
launch_counts = launch_counts[launch_counts['LAUNCH_YEAR'] <= 2026]

# Cumulative
launch_counts['CUMULATIVE'] = launch_counts['COUNT'].cumsum()

fig, ax1 = plt.subplots(figsize=(12, 6))

bars = ax1.bar(launch_counts['LAUNCH_YEAR'], launch_counts['COUNT'],
               color=ACCENT, alpha=0.7, width=0.7, label='Annual Launches')
ax1.set_xlabel('Launch Year')
ax1.set_ylabel('Satellites Launched (per year)', color=ACCENT)
ax1.tick_params(axis='y', labelcolor=ACCENT)

ax2 = ax1.twinx()
ax2.plot(launch_counts['LAUNCH_YEAR'], launch_counts['CUMULATIVE'],
         color=ACCENT2, linewidth=2.5, marker='o', markersize=4, label='Cumulative Fleet')
ax2.set_ylabel('Cumulative Active Satellites', color=ACCENT2)
ax2.tick_params(axis='y', labelcolor=ACCENT2)

# Annotate the inflection point
recent = launch_counts[launch_counts['LAUNCH_YEAR'] >= 2019]
peak_row = recent.loc[recent['COUNT'].idxmax()]
ax1.annotate(f'Peak: {int(peak_row["COUNT"]):,} ({int(peak_row["LAUNCH_YEAR"])})',
             xy=(peak_row['LAUNCH_YEAR'], peak_row['COUNT']),
             xytext=(peak_row['LAUNCH_YEAR'] - 5, peak_row['COUNT'] * 0.85),
             arrowprops=dict(arrowstyle='->', color=ACCENT2, lw=1.5),
             fontsize=11, fontweight='bold', color=ACCENT2)

# Highlight post-2020 region
ax1.axvspan(2019.5, 2026.5, alpha=0.08, color=ACCENT2, label='Post-2020 Acceleration')

ax1.set_title('Launch Year Distribution of Currently Active Satellites', pad=15)
lines1, labels1 = ax1.get_legend_handles_labels()
lines2, labels2 = ax2.get_legend_handles_labels()
ax1.legend(lines1 + lines2, labels1 + labels2, loc='upper left', framealpha=0.9)

chart_launch = fig_to_base64(fig)

# ═══════════════════════════════════════════════════════════════════════
# CHART 2 — Orbital Regime Distribution (Pie + Bar)
# ═══════════════════════════════════════════════════════════════════════
regime_order = ['LEO', 'MEO', 'GEO', 'HEO', 'Other', 'Unknown']
regime_counts = df['ORBIT_REGIME'].value_counts()
regime_counts = regime_counts.reindex([r for r in regime_order if r in regime_counts.index])

fig, (ax_pie, ax_bar) = plt.subplots(1, 2, figsize=(13, 5.5))

colors_pie = [ACCENT, ACCENT3, ACCENT4, ACCENT2, '#607d8b', '#9e9e9e'][:len(regime_counts)]
wedges, texts, autotexts = ax_pie.pie(
    regime_counts.values, labels=regime_counts.index, autopct='%1.1f%%',
    colors=colors_pie, startangle=90, pctdistance=0.82,
    wedgeprops={'edgecolor': 'white', 'linewidth': 2})
for t in autotexts:
    t.set_fontsize(10)
    t.set_fontweight('bold')
ax_pie.set_title('Orbital Regime Share', pad=15)

ax_bar.barh(regime_counts.index[::-1], regime_counts.values[::-1], color=colors_pie[::-1], edgecolor='white')
for i, v in enumerate(regime_counts.values[::-1]):
    ax_bar.text(v + 50, i, f'{v:,}', va='center', fontweight='bold', fontsize=10)
ax_bar.set_xlabel('Number of Satellites')
