import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
from io import BytesIO
import warnings
warnings.filterwarnings('ignore')

# ─── Load & Clean Data ───────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
total_sats = len(df)

# Convert string columns
df['ECCENTRICITY'] = df['ECCENTRICITY'].astype(str).str.strip()
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')

df['MEAN_MOTION'] = pd.to_numeric(df['MEAN_MOTION'], errors='coerce')
df['INCLINATION'] = pd.to_numeric(df['INCLINATION'], errors='coerce')

# Extract launch year from OBJECT_ID (first 4 chars)
df['LAUNCH_YEAR'] = df['OBJECT_ID'].astype(str).str[:4].astype(int)

# ─── Orbital Regime Classification ───────────────────────────────────
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if pd.isna(mm):
        return 'Unknown'
    if ecc is not None and not pd.isna(ecc) and ecc > 0.1 and mm < 10:
        return 'HEO'
    if mm > 14:
        return 'LEO'
    elif mm >= 1.8:
        return 'MEO'
    elif mm >= 0.9:
        return 'GEO'
    else:
        return 'Other'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# ─── Constellation Identification ────────────────────────────────────
def identify_constellation(name):
    name_upper = str(name).upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    elif name_upper.startswith('GPS'):
        return 'GPS'
    elif name_upper.startswith('COSMO-SKYMED') or name_upper.startswith('COSMO'):
        return 'COSMO-SkyMed'
    elif name_upper.startswith('GONETS'):
        return 'Gonets'
    elif name_upper.startswith('GLONASS') or name_upper.startswith('COSMOS') and 'GLONASS' in name_upper:
        return 'GLONASS'
    elif name_upper.startswith('SENTINEL'):
        return 'Sentinel'
    elif name_upper.startswith('PLANET') or name_upper.startswith('FLOCK') or 'DOVE' in name_upper:
        return 'Planet Labs'
    elif name_upper.startswith('YAOGAN'):
        return 'Yaogan'
    elif name_upper.startswith('BEIDOU') or name_upper.startswith('BDS'):
        return 'BeiDou'
    elif name_upper.startswith('GLOBALSTAR'):
        return 'Globalstar'
    elif name_upper.startswith('ORBCOMM'):
        return 'Orbcomm'
    elif name_upper.startswith('SKYSAT'):
        return 'SkySat'
    elif name_upper.startswith('LEO'):
        return 'LEO (various)'
    elif name_upper.startswith('ISS') or name_upper == 'ISS (ZARYA)':
        return 'ISS'
    elif name_upper.startswith('TDRS'):
        return 'TDRS'
    elif name_upper.startswith('NOAA') or name_upper.startswith('GOES'):
        return 'NOAA/GOES'
    elif name_upper.startswith('LANDSAT'):
        return 'Landsat'
    elif name_upper.startswith('SWARM') and ('A' in name_upper or 'B' in name_upper):
        return 'Swarm'
    else:
        return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

# ─── Compute KPIs ────────────────────────────────────────────────────
leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = leo_count / total_sats * 100
starlink_count = len(df[df['CONSTELLATION'] == 'Starlink'])
median_inclination = df['INCLINATION'].median()
post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])
post_2020_share = post_2020_count / total_sats * 100

# ─── Chart Style Setup ───────────────────────────────────────────────
plt.rcParams.update({
    'figure.facecolor': '#ffffff',
    'axes.facecolor': '#f8f9fa',
    'axes.edgecolor': '#dee2e6',
    'axes.grid': True,
    'grid.color': '#e9ecef',
    'grid.linewidth': 0.6,
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.titlesize': 14,
    'axes.titleweight': 'bold',
    'axes.labelsize': 12,
})

ACCENT = '#1a73e8'
ACCENT2 = '#ea4335'
ACCENT3 = '#34a853'
ACCENT4 = '#fbbc04'
PALETTE = ['#1a73e8', '#ea4335', '#34a853', '#fbbc04', '#9c27b0', '#ff6d00', '#00bcd4', '#795548', '#607d8b', '#e91e63']

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=130)
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode()

# ═══════════════════════════════════════════════════════════════════════
# CHART 1 — Launch Year Trend (THE MOST IMPORTANT CHART)
# ═══════════════════════════════════════════════════════════════════════
launch_counts = df.groupby('LAUNCH_YEAR').size().reset_index(name='COUNT')
launch_counts = launch_counts[launch_counts['LAUNCH_YEAR'] <= 2026]

# Cumulative
launch_counts['CUMULATIVE'] = launch_counts['COUNT'].cumsum()

fig, ax1 = plt.subplots(figsize=(12, 6))

bars = ax1.bar(launch_counts['LAUNCH_YEAR'], launch_counts['COUNT'],
               color=ACCENT, alpha=0.7, width=0.7, label='Annual Launches')
ax1.set_xlabel('Launch Year')
ax1.set_ylabel('Satellites Launched (per year)', color=ACCENT)
ax1.tick_params(axis='y', labelcolor=ACCENT)

ax2 = ax1.twinx()
ax2.plot(launch_counts['LAUNCH_YEAR'], launch_counts['CUMULATIVE'],
         color=ACCENT2, linewidth=2.5, marker='o', markersize=4, label='Cumulative Fleet')
ax2.set_ylabel('Cumulative Active Satellites', color=ACCENT2)
ax2.tick_params(axis='y', labelcolor=ACCENT2)

# Annotate the inflection point
recent = launch_counts[launch_counts['LAUNCH_YEAR'] >= 2019]
peak_row = recent.loc[recent['COUNT'].idxmax()]
ax1.annotate(f'Peak: {int(peak_row["COUNT"]):,} ({int(peak_row["LAUNCH_YEAR"])})',
             xy=(peak_row['LAUNCH_YEAR'], peak_row['COUNT']),
             xytext=(peak_row['LAUNCH_YEAR'] - 5, peak_row['COUNT'] * 0.85),
             arrowprops=dict(arrowstyle='->', color=ACCENT2, lw=1.5),
             fontsize=11, fontweight='bold', color=ACCENT2)

# Highlight post-2020 region
ax1.axvspan(2019.5, 2026.5, alpha=0.08, color=ACCENT2, label='Post-2020 Acceleration')

ax1.set_title('Launch Year Distribution of Currently Active Satellites', pad=15)
lines1, labels1 = ax1.get_legend_handles_labels()
lines2, labels2 = ax2.get_legend_handles_labels()
ax1.legend(lines1 + lines2, labels1 + labels2, loc='upper left', framealpha=0.9)

chart_launch = fig_to_base64(fig)

# ═══════════════════════════════════════════════════════════════════════
# CHART 2 — Orbital Regime Distribution (Pie + Bar)
# ═══════════════════════════════════════════════════════════════════════
regime_order = ['LEO', 'MEO', 'GEO', 'HEO', 'Other', 'Unknown']
regime_counts = df['ORBIT_REGIME'].value_counts()
regime_counts = regime_counts.reindex([r for r in regime_order if r in regime_counts.index])

fig, (ax_pie, ax_bar) = plt.subplots(1, 2, figsize=(13, 5.5))

colors_pie = [ACCENT, ACCENT3, ACCENT4, ACCENT2, '#607d8b', '#9e9e9e'][:len(regime_counts)]
wedges, texts, autotexts = ax_pie.pie(
    regime_counts.values, labels=regime_counts.index, autopct='%1.1f%%',
    colors=colors_pie, startangle=90, pctdistance=0.82,
    wedgeprops={'edgecolor': 'white', 'linewidth': 2})
for t in autotexts:
    t.set_fontsize(10)
    t.set_fontweight('bold')
ax_pie.set_title('Orbital Regime Share', pad=15)

ax_bar.barh(regime_counts.index[::-1], regime_counts.values[::-1], color=colors_pie[::-1], edgecolor='white')
for i, v in enumerate(regime_counts.values[::-1]):
    ax_bar.text(v + 50, i, f'{v:,}', va='center', fontweight='bold', fontsize=10)
ax_bar.set_xlabel('Number of Satellites')
ax_bar.set_title('Satellite Count by Regime', pad=15)
ax_bar.xaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{int(x):,}'))

plt.tight_layout()
chart_regime = fig_to_base64(fig)

# ═══════════════════════════════════════════════════════════════════════
# CHART 3 — Top Constellations
# ═══════════════════════════════════════════════════════════════════════
const_counts = df['CONSTELLATION'].value_counts()
top_constellations = const_counts[const_counts.index != 'Other'].head(10]

fig, ax = plt.subplots(figsize=(12, 6))
bars = ax.barh(top_constellations.index[::-1], top_constellations.values[::-1],
               color=PALETTE[:len(top_constellations)][::-1], edgecolor='white', height=0.6)

for i, v in enumerate(top_constellations.values[::-1]):
    pct = v / total_sats * 100
    ax.text(v + 30, i, f'{v:,}  ({pct:.1f}%)', va='center', fontweight='bold', fontsize=10)

# Starlink annotation
if 'Starlink' in top_constellations.index:
    starlink_idx = list(top_constellations.index[::-1]).index('Starlink')
    bars[starlink_idx].set_edgecolor(ACCENT2)
    bars[starlink_idx].set_linewidth(2)

ax.set_xlabel('Number of Active Satellites')
ax.set_title('Top 10 Satellite Constellations by Active Count', pad=15)
ax.xaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{int(x):,}'))

chart_constellations = fig_to_base64(fig)

# ═══════════════════════════════════════════════════════════════════════
# CHART 4 — Constellation vs Non-Constellation (Starlink Impact)
# ═══════════════════════════════════════════════════════════════════════
fig, ax = plt.subplots(figsize=(8, 5))
categories = ['Starlink', 'Other Constellations', 'Independent Satellites']
starlink_v = starlink_count
other_const = int(const_counts[const_counts.index != 'Other'].sum()) - starlink_count
independent = int(const_counts.get('Other', 0))
vals = [starlink_v, other_const, independent]
colors_impact = [ACCENT2, ACCENT4, ACCENT]

wedges, texts, autotexts = ax.pie(vals, labels=categories, autopct='%1.1f%%',
    colors=colors_impact, startangle=90, wedgeprops={'edgecolor': 'white', 'linewidth': 2},
    pctdistance=0.75)
for t in autotexts:
    t.set_fontsize(11)
    t.set_fontweight('bold')
ax.set_title('Starlink vs. Rest of Active Fleet', pad=15)

chart_starlink_impact = fig_to_base64(fig)

# ═══════════════════════════════════════════════════════════════════════
# CHART 5 — Inclination Distribution (Histogram)
# ═══════════════════════════════════════════════════════════════════════
fig, ax = plt.subplots(figsize=(11, 5))
ax.hist(df['INCLINATION'].dropna(), bins=90, color=ACCENT, alpha=0.75, edgecolor='white', linewidth=0.3)
ax.axvline(median_inclination, color=ACCENT2, linestyle='--', linewidth=2,
           label=f'Median: {median_inclination:.1f}°')
ax.set_xlabel('Inclination (degrees)')
ax.set_ylabel('Number of Satellites')
ax.set_title('Distribution of Orbital Inclination', pad=15)
ax.legend(fontsize=11, framealpha=0.9)
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{int(x):,}'))

chart_inclination = fig_to_base64(fig)

# ═══════════════════════════════════════════════════════════════════════
# CHART 6 — Eccentricity Distribution (log scale)
# ═══════════════════════════════════════════════════════════════════════
ecc_valid = df['ECCENTRICITY'].dropna()
