ax.hist(mm_valid, bins=120, color=ACCENT4, alpha=0.75, edgecolor='white', linewidth=0.3)

# Add regime boundary lines
ax.axvline(14, color=ACCENT2, linestyle='--', linewidth=1.5, alpha=0.8, label='LEO/MEO boundary (14 rev/day)')
ax.axvline(1.8, color='#9c27b0', linestyle='--', linewidth=1.5, alpha=0.8, label='MEO/GEO boundary (1.8 rev/day)')
ax.set_xlabel('Mean Motion (revolutions/day)')
